from pathlib import Path
import base64, html, json, re, struct, hashlib, zipfile

ROOT=Path('/Users/IDC2.5/jv')
PACK=ROOT/'design-reference'
screens=json.loads((PACK/'brief/screens.json').read_text())
shortlist=[1,3,5,6,9,10,11,12,17,18]
def data(path):
    return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
def esc(s): return html.escape(str(s),quote=True)
cards=[]
assets=[]
for s in screens:
    p=PACK/'screens'/f"{s['n']:02d}-{s['id']}.png"
    raw=p.read_bytes()
    assert raw[:8]==b'\x89PNG\r\n\x1a\n',str(p)
    w,h=struct.unpack('>II',raw[16:24])
    assets.append({'screen':s['n'],'title':s['title'],'file':str(p.relative_to(PACK)),'width':w,'height':h,'sha256':hashlib.sha256(raw).hexdigest()})
    src=data(p)
    cards.append(f'<article class="screen-card" data-top="{str(s["n"] in shortlist).lower()}"><button class="image-button" data-screen="{s["n"]}" aria-label="Open screen {s["n"]}: {esc(s["title"])}"><img src="{src}" alt="{esc(s["title"])} — JOVRA iOS reference" width="{w}" height="{h}" loading="lazy"></button><div class="card-caption"><span class="number">{s["n"]:02d}</span><h3>{esc(s["title"])}</h3></div></article>')
logo_names=[('01-court-arc','Court Arc','94','Selected'),('02-stringbed','Stringbed','86','Alternative'),('03-flight','Flight','88','Alternative'),('04-baseline','Baseline','90','Alternative')]
logos=[]
for f,name,score,state in logo_names:
    p=PACK/'logos'/f'{f}.png'
    logos.append(f'<figure class="logo-card"><img src="{data(p)}" alt="JOVRA {name} logo concept" loading="lazy"><figcaption><b>{name}</b><span>{state} · {score}/100 creative fit</span></figcaption></figure>')
