def inline(s):
    s=esc(s)
    s=re.sub(r'\*\*(.*?)\*\*',r'<strong>\1</strong>',s)
    s=re.sub(r'\[([^\]]+)\]\((https?://[^)]+)\)',r'<a href="\2">\1</a>',s)
    return s
lines=(PACK/'brief/research.md').read_text().splitlines()
parts=[];i=0
while i<len(lines):
    line=lines[i]
    if line.startswith('# '): i+=1;continue
    if line.startswith('## '):
        parts.append(f'<section aria-labelledby="section-{i}"><h2 id="section-{i}">{inline(line[3:])}</h2></section>')
    elif line.startswith('|'):
        rows=[]
        while i<len(lines) and lines[i].startswith('|'):
            cols=[c.strip() for c in lines[i].strip('|').split('|')]
            if not all(re.fullmatch(r'[-: ]+',c) for c in cols): rows.append(cols)
            i+=1
        parts.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in rows[1:])+'</tbody></table></div>')
        continue
    elif line.startswith('- '): parts.append('<p style="margin:12px 0">'+inline(line[2:])+'</p>')
    elif line.strip():parts.append('<p style="margin:14px 0;color:var(--muted)">'+inline(line)+'</p>')
    i+=1
report='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>JOVRA Research — October 7, 2026</title><style>'+base_css+':root{--bg:#092a25;--paper:#0c3028;--paper-2:#123c33;--ink:#f4f1e8;--muted:#bdcfc5;--accent:#d7f56a;--line:#35544a;--blue:#d7f56a}body{background:var(--bg)}.hero h1{font-size:clamp(2.3rem,5vw,4rem)}a{overflow-wrap:anywhere}th,td{min-width:130px}@media print{body{background:#fff;color:#182f29}:root{--muted:#182f29;--ink:#182f29;--line:#ccc;--blue:#092a25}.panel,.verdict-card{background:#eee;box-shadow:none}h3,th{color:#182f29}}</style></head><body><main><header class="hero"><div><p class="eyebrow">JOVRA · Research and build direction · October 7, 2026</p><h1>Save the game.<br>Make the evidence useful.</h1><p class="summary">Build reliable local recording and clear video review first. Add optional Google Drive archiving and validate each analysis capability before calling it automatic.</p><div style="margin-top:20px"><span class="chip green">3 app references inspected</span><span class="chip blue">20 original screen concepts</span><span class="chip amber">Application not built</span></div></div><aside class="verdict-card"><strong>Local first. Drive optional.</strong><span>Competitor workflows support point review, stroke detail and comparison. Historical complaints motivate recovery and correction tests; they do not prove current competitor failure rates.</span></aside></header>'+''.join(parts)+'<p class="footer-note">Evidence: current US App Store listings and visible screenshot previews, selected dated reviews, release notes, and linked Apple/Google/AWS documentation. No competitor hands-on benchmark or application runtime test was performed. Research was rechecked against contrary release-note and developer-response evidence. No prior report is superseded. <a href="index.html">Return to the visual collection</a>.</p></main></body></html>'
